//! 🧪️ The actual original caller transfers one real output queue once and finances its paired close.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneGrant;
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn original_output_hook_is_affine_across_queue_handoff_and_exact_denials(){
 let mut scope=semio_framework_plugin::artifact_app_laws::OriginalFixtureScope::admit();let cx=scope.cx();let mut original=None;assert!(ArtifactOutputChunks::original_birth_admit(ArtifactOutputChunks::CHUNK_BYTES,&mut original,cx).unwrap());let identity=original.as_ref().unwrap().original_identity();let operation=Operation::new(cx.operation(),RevisionId(1),cx.generation(),0);let demand=RetirementDemand{copy_bytes:2*std::mem::size_of::<LayoutOriginalExportWork>(),depth:1,..Default::default()};assert!(cx.retained_work_can_enter(demand));let(work,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||LayoutOriginalExportWork::new(LayoutExportKind::Svg,operation));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}).unwrap();let mut work=work;let demand=LayoutOriginalExportWork::transition::<ArtifactOutputChunks>();
 for axis in 0..3{let mut g=exact(demand);match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes-=1,_=>g.maximum_depth-=1}let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(g,|same|work.receive_original_output_chunks(&mut original,same)));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(original.as_ref().unwrap().original_identity(),identity);assert!(!work.output_received);assert!(work.owners.original().unwrap().chunks.is_none())}
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(exact(demand),|same|work.receive_original_output_chunks(&mut original,same)));assert!(result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(original.is_none());assert_eq!(work.owners.original().unwrap().chunks.as_ref().unwrap().original_identity(),identity);
 let transfer=LayoutOriginalExportWork::transition::<ArtifactOutputChunks>();assert!(cx.retained_work_can_enter(transfer));let carried=work.owners.original_mut().unwrap().chunks.take();cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:transfer.copy_bytes,..Default::default()}).unwrap();let before=cx.retained_progress();assert!(cx.with_retained_loan(RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0},|same|work.receive_original_output_chunks(&mut original,same)).unwrap());assert_eq!(cx.retained_progress(),before);assert!(original.is_none());assert_eq!(carried.as_ref().unwrap().original_identity(),identity);assert!(cx.retained_work_can_enter(transfer));work.owners.original_mut().unwrap().chunks=carried;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:transfer.copy_bytes,..Default::default()}).unwrap();
 work.begin_close();for _ in 0..10000{if work.terminal_is_empty(){break}let demand=work.close_demand(cx.retained_grant().maximum_copy_bytes).unwrap();let mut g=exact(demand);if demand.copy_bytes>0{g.maximum_copy_bytes-=1}else if demand.capacity_bytes>0{g.maximum_capacity_bytes-=1}else if demand.release_bytes>0{g.maximum_release_bytes-=1}else{g.maximum_items=0}let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(g,|same|work.close_step(same)));assert_eq!(result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(exact(demand),|same|work.close_step(same)));let progress=result.unwrap().progress();assert!(progress.fits(exact(demand)));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(cx.retained_progress().retained_capacity_bytes-before.retained_capacity_bytes,progress.retained_capacity_bytes);assert_eq!(cx.retained_progress().released_bytes-before.released_bytes,progress.released_bytes)}assert!(work.terminal_is_empty());scope.retire();
}
